    /// (item 28) the give-up cap boundary: an era at exactly the cap is
    /// cancelled; one second younger is not.
    #[test]
    fn adoption_give_up_fires_only_at_the_cap() {
        let now = Instant::now();
        let cap = Duration::from_secs(600);
        assert!(!adoption_give_up_due(
            now - Duration::from_secs(599),
            now,
            cap
        ));
        assert!(adoption_give_up_due(
            now - Duration::from_secs(600),
            now,
            cap
        ));
    }

    /// (item 28) cancel-on-supersede: a SECOND, heavier adoption while the
    /// first adoption's bodies are still queued DROPS the old queue (only
    /// the new branch remains) and bumps the switch epoch — the live
    /// adopt-fail-remint loop re-queued the same heights every re-judge
    /// cycle until the outstanding cap froze dispatch.
    #[test]
    fn a_second_adoption_supersedes_the_first_era() {
        let _live_store_serial = lock_live_store_tests();
        let l_a = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let l_b = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let mut a = i2p_test_peer(std::net::TcpStream::connect(l_a.local_addr().unwrap()).unwrap());
        let mut b = i2p_test_peer(std::net::TcpStream::connect(l_b.local_addr().unwrap()).unwrap());
        a.label = "in:pc.i2p".into();
        b.label = "out:other.onion".into();
        let mut stg = synthetic_chain(100, 105);
        let mut recon = ReconAcc::default();
        let mut pend = VecDeque::new();
        let mut stats = Stats::default();

        // era 1: A's heavier branch — 4 blocks forking at h102 → ADOPTED
        let fork_hash = stg.entry_abs(102).unwrap().hash;
        let mut prev = fork_hash;
        let mut branch_a: Vec<Block> = Vec::new();
        for i in 0..4u8 {
            let hdr = mk_header(prev, 0x80 + i, 0x2000_ffff);
            prev = hdr.hash();
            branch_a.push(hdr);
        }
        recon_dispatch(&mut stg, &mut a, &branch_a, &mut recon, &mut pend, &mut stats)
            .expect("era-1 adoption dispatch ok");
        assert_eq!(pend.len(), 4, "era-1 bodies are pending");
        assert_eq!(recon.switch_epoch, 1);
        let era1_first = pend.front().unwrap().0;

        // era 2: B's heavier branch — 5 blocks forking at h101 (BELOW the
        // post-rollback tip: a branch that chains onto the tip is a normal
        // extension, not a competing branch), distinct seeds → Switch again;
        // era-1's queued bodies must DROP
        let fork2_hash = stg.entry_abs(101).unwrap().hash;
        let mut prev2 = fork2_hash;
        let mut branch_b: Vec<Block> = Vec::new();
        for i in 0..5u8 {
            let hdr = mk_header(prev2, 0x90 + i, 0x2000_ffff);
            prev2 = hdr.hash();
            branch_b.push(hdr);
        }
        recon_dispatch(&mut stg, &mut b, &branch_b, &mut recon, &mut pend, &mut stats)
            .expect("era-2 adoption dispatch ok");
        assert_eq!(recon.switch_epoch, 2, "the switch epoch advanced");
        assert_eq!(pend.len(), 5, "era-1's queue was replaced, not appended to");
        assert_ne!(
            pend.front().unwrap().0,
            era1_first,
            "the front is era-2's first body, not a stale era-1 hash"
        );
        assert_eq!(
            recon.branch_source.as_deref(),
            Some("out:other.onion"),
            "the new adoption owns the body source"
        );
    }

    /// (item 29) graceful stop mid-backfill: the stop predicate fires part
    /// way through pass 1 — the pass returns true, the floor is pinned at
    /// the window top (item-24-r2 partial semantics: every absent coin
    /// honestly unresolvable until the retry lane completes coverage), and
    /// the heights folded before the stop STAY in the insert-only map. A
    /// follow-up pass with no stop completes normally (false).
    #[test]
    fn backfill_graceful_stop_pins_the_floor_and_reports_the_stop() {
        let mut prev: Hash = [0xABu8; 32];
        let mut blocks: Vec<Block> = Vec::new();
        for h in 0..=30u64 {
            let b = mk_body_block(
                prev,
                0x60 + h as u8,
                0x2000_ffff,
                1_700_000_000u32 + (h * 600) as u32,
            );
            prev = b.hash();
            blocks.push(b);
        }
        let mut stg = chain_state_from_window(0, &blocks);
        // records [15..=30]: the backfill folds [0..15) in pass 1
        stg.records = blocks[15..]
            .iter()
            .enumerate()
            .map(|(i, b)| stg.record_of(b, 15 + i as u64))
            .collect();
        let rpc = Rpc::new("127.0.0.1", 1, "", ""); // dead port: pass 2 never answers
        // stop AFTER 4 heights folded (one call per pass-1 height)
        let calls = std::sync::atomic::AtomicUsize::new(0);
        let stopped = boot_backfill_kernel_window(&mut stg, &rpc, &|| {
            let n = calls.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
            n >= 4
        });
        assert!(stopped, "the stop predicate must end the pass with true");
        assert_eq!(
            stg.utxo_floor_rel,
            stg.entries.len(),
            "floor pinned at the window top — honest non-contiguous coverage"
        );
        // the checkpoint fires PER HEIGHT: called at rel 0..=4 (stop on the
        // 5th) — four heights were queued for pass 2 (no live store in
        // tests: pass-1 folds come from the store only)
        assert_eq!(
            calls.load(std::sync::atomic::Ordering::SeqCst),
            5,
            "one checkpoint call per pass-1 height before the stop"
        );
        // a fresh pass with no stop runs to completion (false) — pass 2
        // finds no listener and the floor stays pinned honestly
        let stopped2 = boot_backfill_kernel_window(&mut stg, &rpc, &|| false);
        assert!(!stopped2, "an un-stopped pass reports false");
        assert_eq!(
            stg.utxo_floor_rel,
            stg.entries.len(),
            "pass 2 finds no listener — floor stays pinned honestly"
        );
    }



    /// (item-23 never-pin rule, socket-level) a FAILED send never happened:
    /// driving the production dispatch sequence (pop → group → resolve →
    /// send) against a dead session asserts nothing was recorded — no
    /// outstanding entry, no BodyTries — and the batch is back at the queue
    /// FRONT in chain order.
    #[test]
    fn send_failure_records_no_dispatch_via_their_pipeline() {
        let l_out = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let mut out =
            i2p_test_peer(std::net::TcpStream::connect(l_out.local_addr().unwrap()).unwrap());
        out.label = "out:only".into();
        out.outbound = true;
        out.sess.shutdown(); // the send MUST fail
        let mut peers = vec![out];
        let b1 = [0xB1u8; 32];
        let b2 = [0xB2u8; 32];
        let mut pending: VecDeque<(Hash, u64)> = VecDeque::from([(b1, 65u64), (b2, 66u64)]);
        let mut outstanding: HashMap<Hash, u64> = HashMap::new();
        let mut body_tries: HashMap<Hash, BodyTries> = HashMap::new();
        // the production dispatch sequence for one group
        let mut group: Vec<(u32, Hash, u64)> = Vec::new();
        while group.len() < 2 {
            match pending.pop_front() {
                Some((hash, height)) => {
                    if !outstanding.contains_key(&hash) {
                        group.push((tri7_core::p2p::MSG_BLOCK, hash, height));
                    }
                }
                None => break,
            }
        }
        assert_eq!(group.len(), 2);
        let body_peer = resolve_body_send_target(
            None,
            peers.as_mut_slice(),
            &[],
            &HashMap::new(),
            0,
        )
        .expect("the (dead) session still resolves as the target");
        let inv: Vec<(u32, Hash)> = group.iter().map(|(t, h, _)| (*t, *h)).collect();
        let body = tri7_core::p2p::build_getdata(&inv);
        assert!(
            body_peer
                .sess
                .send("getdata", &body, &mut Stats::default())
                .is_err(),
            "the killed session must fail the send"
        );
        // (never-pin) nothing recorded, batch requeued at the FRONT in chain order
        let unsent: Vec<(Hash, u64)> = group.iter().map(|(_, h, ht)| (*h, *ht)).collect();
        requeue_unsent_batch(&mut pending, &unsent);
        assert!(
            outstanding.is_empty(),
            "a failed send must not create outstanding entries"
        );
        assert!(
            body_tries.is_empty(),
            "a failed send must not record BodyTries rotation memory"
        );
        assert_eq!(pending.len(), 2, "the batch must be back in the queue");
        assert_eq!(pending[0], (b1, 65), "chain order preserved at the front");
    }

    /// A PoW-shaped BODY block whose header doubles as the served header
    /// (recon) and the served body (validate): one coinbase tx, merkle field
    /// recomputed over vtx so header agreement + structure checks pass.
    fn mk_body_block(prev: Hash, merkle_seed: u8, bits: u32, time: u32) -> Block {
        let cb = Tx {
            version: 1,
            time,
            vin: vec![crate::Vin {
                prev_hash: [0u8; 32],
                prev_n: u32::MAX,
                script_sig: vec![merkle_seed],
                sequence: u32::MAX,
            }],
            vout: vec![crate::Vout {
                value: 1,
                script_pubkey: vec![0x51],
            }],
            locktime: 0,
        };
        let mut b = Block {
            version: 1,
            prev_hash: prev,
            merkle_root: [merkle_seed; 32],
            time,
            bits,
            nonce: 0,
            vtx: vec![cb],
            block_sig: vec![],
        };
        b.merkle_root = b.merkle_root();
        // mine the header: the full live gate checks the PoW target
        let (target, neg, ovf) = set_compact(bits);
        assert!(!neg && !ovf && !target.is_zero(), "degenerate test bits");
        while U256::from_little_endian(&b.hash()) > target {
            b.nonce = b.nonce.wrapping_add(1);
        }
        b
    }

    /// (fz-rec fix 3 era) THE adoption-persistence reproduction: a peer 1999
    /// blocks ahead, the judge switches, and the ADOPTION PIPELINE (getdata →
    /// block → validate → advance) must DRAIN to the branch tip; the next
    /// identical reply re-judges Ignored — no re-fire, no re-adopt loop.
    #[test]
    fn recon_adoption_of_1999_block_branch_persists_tip_and_does_not_refire() {
        let _live_store_serial = lock_live_store_tests();
        // from-zero shape, REAL chained headers h0..h64 (the served reply
        // re-serves our own tip header — the pre-fix parity-locator anchor
        // shape — so the reply's known prefix must hash-match our entries)
        let mut base_blocks: Vec<Block> = Vec::new();
        let mut prev: Hash = [0xAAu8; 32];
        for h in 0..=64u64 {
            let b = mk_body_block(
                prev,
                0x10 + h as u8,
                0x2000_ffff,
                1_700_000_000u32 + (h * 600) as u32,
            );
            prev = b.hash();
            base_blocks.push(b);
        }
        let mut stg = ChainState {
            base: 0,
            entries: base_blocks
                .iter()
                .enumerate()
                .map(|(h, b)| IndexEntry {
                    height: h,
                    hash: b.hash(),
                    prev_hash: b.prev_hash,
                    time: b.time,
                    bits: b.bits,
                    is_proof_of_stake: false,
                    entropy_bit: b.hash()[0] & 1,
                    stake_modifier: h as u64,
                    generated_stake_modifier: true,
                    hash_proof_of_stake: [0u8; 32],
                })
                .collect(),
            checksums: vec![7; 65],
            utxo: WindowOutputs::new(),
            records: Vec::new(),
            no_trim: true, // from-zero: FULL history window
            pending_headers: HashMap::new(),
            tip_height: 64,
            tip_hash: base_blocks[64].hash(),
            daemon_tip: Some(64),
            last_advance_utc: String::new(),
            peers_connected: 0,
            last_peer_utc: None,
            staking_impaired: None,
            utxo_floor_rel: 0,
        };
        let mut recon = ReconAcc::default();
        let mut pend: VecDeque<(Hash, u64)> = VecDeque::new();
        let mut stats = Stats::default();
        let rpc = Rpc::new("127.0.0.1", 1, "", "");

        // a peer 1999 blocks ahead: branch h65..h2063 chaining to our tip,
        // same bits → strictly heavier by length (our work above the fork 0)
        let mut branch: Vec<Block> = Vec::new();
        let mut bprev = base_blocks[64].hash();
        for i in 0..1999u32 {
            let time = 1_700_000_000u32 + ((65 + i as u64) * 600) as u32;
            let hdr = mk_body_block(bprev, (0x40 + (i % 190) as u8), 0x2000_ffff, time);
            bprev = hdr.hash();
            branch.push(hdr);
        }
        let branch_tip_hash = branch.last().unwrap().hash();
        // the reply as the PRE-FIX parity locator produced it: anchor at h63,
        // first element = OUR OWN h64 header, then the 1999 new headers
        let mut reply = vec![base_blocks[64].clone()];
        reply.extend(branch.iter().cloned());
        assert_eq!(reply.len(), 2000); // RECON_HEADERS_CAP — judge-early fires

        // judge: Switch, fork at h64, adopt ALL 1999 via the validated body path
        match recon_intake(&mut stg, &reply, &mut recon, &mut pend, &mut stats) {
            ReconOutcome::Switched { fork, adopted } => {
                assert_eq!(fork, 64);
                assert_eq!(adopted, 1999);
            }
            other => panic!("expected Switched, got {:?}", other),
        }
        assert_eq!(
            stg.tip_height, 64,
            "header-work switch never rolls back before a body validates"
        );
        assert_eq!(pend.len(), 1999);
        assert_eq!(pend[0], (branch[0].hash(), 65));
        assert_eq!(pend[1998], (branch[1998].hash(), 2063));
        assert_eq!(stats.reorgs, 0, "selection is not an executed reorg");
        // the fork IS our tip here, so the branch's first body (h65) links
        // directly and the deferred record is simply consumed by it.
        let pending = pending_adoption_for(&branch[0].hash(), Instant::now())
            .expect("branch recorded as pending");
        assert_eq!(pending.fork_h, 64);
        clear_pending_adoption();

        // THE ADOPTION PIPELINE (item-23 shape: pop in chain order, pin ONLY
        // on a successful send — here the peer serves every body): with the
        // pipeline it drains to the branch tip.
        let bodies: HashMap<Hash, Block> =
            branch.iter().map(|b| (b.hash(), b.clone())).collect();
        let mut outstanding: HashMap<Hash, u64> = HashMap::new();
        loop {
            if stg.tip_height == 64 + 1999 {
                break;
            }
            let (hash, height) = match pend.pop_front() {
                Some((h, ht)) => (h, ht),
                None => panic!(
                    "adoption queue drained before the tip: stalled at h{} with {} queued",
                    stg.tip_height,
                    outstanding.len()
                ),
            };
            if outstanding.contains_key(&hash) {
                continue;
            }
            outstanding.insert(hash, height);
            let b = bodies
                .get(&hash)
                .expect("peer served a body we never adopted a header for");
            let header = stg.pending_headers.remove(&hash);
            let prev_entry = stg.entries.last().cloned().unwrap();
            let height_abs = stg.tip_height + 1;
            let outcome = validate_block(
                &stg,
                &rpc,
                &mut stats,
                b,
                &BlockCtx {
                    height_abs,
                    header: header.as_ref(),
                    prev_entry,
                    live: true,
                },
            )
            .expect("adopted body must pass the full live gate");
            advance_with_block(&mut stg, &rpc, &mut stats, b, &outcome)
                .expect("adopted body must advance the tip");
            outstanding.remove(&hash);
        }
        // the adopted branch PERSISTED: tip is the peer's branch tip exactly
        assert_eq!(stg.tip_height, 2063);
        assert_eq!(stg.tip_hash, branch_tip_hash);
        assert!(pend.is_empty(), "pipeline must have consumed the whole queue");
        assert!(stg.pending_headers.is_empty());
        assert!(
            outstanding.is_empty(),
            "no getdata may stay outstanding after the drain"
        );

        // THE NEXT TICK MUST NOT RE-FIRE: the identical 2000-header reply is
        // now ALL our own entries — nothing new to judge, no rollback, no
        // re-queue, no second adoption
        let mut pend2: VecDeque<(Hash, u64)> = VecDeque::new();
        match recon_intake(&mut stg, &reply, &mut recon, &mut pend2, &mut stats) {
            ReconOutcome::Ignored => {}
            other => panic!(
                "reconciliation re-fired on the adopted branch: {:?}",
                other
            ),
        }
        assert_eq!(stats.reorgs, 0, "no reorg ever executed in this scenario");
        assert!(pend2.is_empty(), "re-fire must not re-queue the same bodies");
    }

    /// (item 21) A batch that chains onto our tip claims its last served
    /// header: tip + len at the batch's last hash. This is the claim a
    /// healthy ahead-of-us peer leaves behind — the verdict must NOT call it
    /// divergent once the hashes are queued (bodies in flight).
    #[test]
    fn extending_batch_claim_records_the_served_tip() {
        let _live_store_serial = lock_live_store_tests();
        let mut stg = synthetic_chain(100, 105);
        let mut prev = stg.tip_hash;
        let mut batch: Vec<Block> = Vec::new();
        for i in 0..3u8 {
            let hdr = mk_header(prev, 0x60 + i, 0x2000_ffff);
            prev = hdr.hash();
            batch.push(hdr);
        }
        let (ch, chash) = claim_from_extending_batch(stg.tip_height, &batch);
        assert_eq!(ch, 108);
        assert_eq!(chash, batch.last().unwrap().hash());
        // before the headers are queued the claim looks divergent (taller +
        // unknown) — the window re-ask it would fire is harmless and pulls
        // the missing blocks; after intake queues them the verdict is false
        assert_eq!(
            claim_divergence_verdict(&stg, Some((ch, chash))),
            Some(true)
        );
        for hdr in &batch {
            stg.pending_headers.insert(hdr.hash(), hdr.clone());
        }
        assert_eq!(
            claim_divergence_verdict(&stg, Some((ch, chash))),
            Some(false)
        );
    }

    /// (item 19) streak bookkeeping: consecutive empties climb; an empty
    /// echo of an in-flight re-ask neither counts nor resets; any non-empty
    /// reply clears both the in-flight flag and the streak.
    #[test]
    fn empty_reply_streak_bookkeeping_counts_and_resets() {
        let mut recon = ReconAcc::default();
        assert_eq!(recon.empty_tip_poll_streak, 0);
        // three consecutive empties (nothing in flight) climb to N
        for _ in 0..3 {
            note_reply_empty(&mut recon);
        }
        assert_eq!(recon.empty_tip_poll_streak, 3);
        // the echo of our own in-flight window re-ask: neither counts nor
        // resets (it is "no overlap", not evidence)
        recon.awaiting_window_reply = true;
        note_reply_empty(&mut recon);
        assert_eq!(recon.empty_tip_poll_streak, 3);
        // a non-empty reply answers whatever was in flight: full reset
        note_reply_nonempty(&mut recon);
        assert!(!recon.awaiting_window_reply);
        assert_eq!(recon.empty_tip_poll_streak, 0);
        // the next empty counts from one again
        note_reply_empty(&mut recon);
        assert_eq!(recon.empty_tip_poll_streak, 1);
    }

    /// (item 33) THE LATCH: an empty echo of the window re-ask pins the
    /// in-flight flag only for WINDOW_REASK_TIMEOUT — after that, empty
    /// replies count toward the streak again and the trigger re-fires
    /// (cooldown permitting): the loop re-arms WITHOUT a restart. The live
    /// 2026-11-18 split muted Pi (13:34:21Z) and DNS3 (13:38:32Z) for
    /// 17-28 min because the flag had no timeout: every later empty reply
    /// was classified as that one request's echo until the operator
    /// restart. A FRESH re-ask (within the timeout) still swallows its echo,
    /// and an UNSTAMPED legacy flag still latches — the r5 disjoint-peer pin
    /// is preserved in both shapes.
    #[test]
    fn window_reask_latch_time_boxes_and_re_arms_without_a_restart() {
        let mut recon = ReconAcc::default();
        // fresh send: the echo is swallowed (r5, unchanged)...
        mark_window_reask(&mut recon);
        note_reply_empty(&mut recon);
        assert_eq!(recon.empty_tip_poll_streak, 0, "a fresh echo is not evidence");
        assert!(awaiting_window_reask(&recon));
        // ...and while the latch is fresh the trigger cannot fire through it
        assert!(!empty_reply_fork_recon_due(
            2214624, 2214624, 3, awaiting_window_reask(&recon), None, None
        ));
        // the answer never came / was empty: past the timeout the latch expires
        recon.window_reask_at =
            Some(Instant::now() - WINDOW_REASK_TIMEOUT - Duration::from_secs(1));
        assert!(!awaiting_window_reask(&recon), "the latch must time-box");
        // empty replies count toward the streak again...
        note_reply_empty(&mut recon);
        assert_eq!(recon.empty_tip_poll_streak, 1);
        // ...and once the streak re-accumulates (and the 60 s cooldown from
        // the original send has passed) the trigger fires again: RE-ARMED
        recon.empty_tip_poll_streak = EMPTY_REPLY_EVIDENCE_STREAK;
        recon.empty_fork_recon_at = Some(Instant::now() - Duration::from_secs(120));
        assert!(
            empty_reply_fork_recon_due(
                2214624,
                2214624,
                recon.empty_tip_poll_streak,
                awaiting_window_reask(&recon),
                recon.empty_fork_recon_at,
                None,
            ),
            "the loop must re-arm without a restart"
        );
        // an UNSTAMPED legacy flag (awaiting set directly, no stamp — the
        // pre-item-33 shape any unmigrated path could produce) still latches
        let mut legacy = ReconAcc::default();
        legacy.awaiting_window_reply = true;
        note_reply_empty(&mut legacy);
        assert_eq!(legacy.empty_tip_poll_streak, 0);
    }

    /// (item 33) the poll locator carries the window stride: tip first, the
    /// parity prev second, then every RECON_LOCATOR_STEP-th entry down to
    /// the base — deepest-first throughout, capped at RECON_LOCATOR_MAX,
    /// genesis-safe.
    #[test]
    fn tip_poll_locator_carries_the_window_stride() {
        let stg = synthetic_chain(100, 500);
        let loc = tip_poll_locator(&stg, true);
        assert_eq!(loc[0], stg.tip_hash);
        assert_eq!(loc[1], stg.entry_abs(499).unwrap().hash);
        assert!(
            loc.contains(&stg.entry_abs(372).unwrap().hash),
            "the tip-128 stride anchor is present"
        );
        assert!(
            loc.contains(&stg.entry_abs(100).unwrap().hash),
            "the base anchor terminates the stride"
        );
        assert!(loc.len() <= RECON_LOCATOR_MAX);
        // non-parity: no prev, strides still present
        let loc2 = tip_poll_locator(&stg, false);
        assert_eq!(loc2[0], stg.tip_hash);
        assert_ne!(loc2[1], stg.entry_abs(499).unwrap().hash);
        assert!(loc2.contains(&stg.entry_abs(100).unwrap().hash));
        // genesis: tip-hash only, never underflows (the r-lapstop pin)
        let g = synthetic_chain(0, 0);
        assert_eq!(tip_poll_locator(&g, true), vec![g.tip_hash]);
        // a deep window hits the cap exactly, never exceeds it
        let deep = synthetic_chain(0, 20_000);
        assert_eq!(tip_poll_locator(&deep, true).len(), RECON_LOCATOR_MAX);
    }

    /// (item 33) THE 2026-11-18 FLEET SPLIT, REPLAYED AT THE JUDGE: an
    /// equal-work race forks the fleet at h2214621/22; both sides extend and
    /// the heavier side solo-climbs. The lighter follower's poll now carries
    /// the window stride, so the heavier peer resolves a SHARED anchor below
    /// the fork and serves its whole branch IN THE POLL REPLY — the
    /// follower's judge adopts it in ONE exchange, with no re-ask
    /// round-trip and no manual restart. The old locator ([tip]/[tip, prev])
    /// held nothing the forked peer could anchor: every reply was empty, the
    /// re-ask round-trip aimed at a same-tip peer that answered empty, the
    /// in-flight latch pinned the loop mute, and the branch flowed only via
    /// operator restarts (25+ min stuck; Pi/DNS3 sat frozen at h2214624).
    #[test]
    fn stride_poll_reply_adopts_the_heavier_split_branch_in_one_exchange() {
        let _live_store_serial = lock_live_store_tests();
        clear_pending_adoption();
        // the lighter follower: window base h2214496, tip h2214624 — its own
        // 3-block branch above the shared ancestor h2214621 (the live
        // split's shape; synthetic entry hashes are a deterministic function
        // of height, so every entry below the fork is shared ancestry)
        let fork_h = 2214621;
        let mut stg = synthetic_chain(2214496, 2214624);
        let mut recon = ReconAcc::default();
        let mut pend: VecDeque<(Hash, u64)> = VecDeque::new();
        let mut stats = Stats::default();

        // the poll locator the follower sends: it MUST contain a shared
        // below-fork anchor (tip-128) — the entries the OLD locator carried
        // ([tip, prev]) are both fork-side, which is why a forked peer
        // could never anchor them and answered empty every time
        let loc = tip_poll_locator(&stg, true);
        assert_eq!(loc[0], stg.tip_hash, "tip first (the fz-rec fix 2 order)");
        assert_eq!(loc[1], stg.entry_abs(2214623).unwrap().hash, "parity prev second");
        assert!(
            loc.contains(&stg.entry_abs(2214496).unwrap().hash),
            "the stride anchor at tip-128 (shared ancestry) is in the poll locator"
        );
        assert!(loc.len() <= RECON_LOCATOR_MAX);
        assert!(
            !loc[0..2].contains(&stg.entry_abs(fork_h).unwrap().hash),
            "the pre-stride anchors sit ABOVE the fork — the old all-empty shape"
        );

        // the heavier side solo-climbed: 9 blocks above the shared ancestor,
        // each 256x harder (0x1e00ffff) — strictly more TOTAL work above the
        // fork than the follower's 3-block branch, at a taller tip (the DNS2
        // branch: h2214622..4630)
        let ancestor = stg.entry_abs(fork_h).unwrap().hash;
        let mut prev = ancestor;
        let mut branch: Vec<Block> = Vec::new();
        for i in 0..9u8 {
            let hdr = mk_header(prev, 0x60 + i, 0x1e00_ffff);
            prev = hdr.hash();
            branch.push(hdr);
        }
        // THE EXCHANGE: the branch arrives as the poll reply (its first
        // header does not chain to our tip → the competing-branch judge).
        // One exchange adopts it — the acceptance bar is "the heavier branch
        // must be adopted by the lighter side within N poll cadences with
        // zero manual restarts"; this is cadence 1, restarts 0.
        match recon_intake(&mut stg, &branch, &mut recon, &mut pend, &mut stats) {
            ReconOutcome::Switched { fork, adopted } => {
                assert_eq!(fork, fork_h);
                assert_eq!(adopted, 9);
            }
            other => panic!("expected Switched, got {:?}", other),
        }
        // (T7-03) headers-only selection: no rollback until a body validates
        assert_eq!(stg.tip_height, 2214624);
        assert_eq!(pend.len(), 9);
        assert_eq!(pend[0], (branch[0].hash(), fork_h + 1));
        let pending = pending_adoption_for(&branch[0].hash(), Instant::now())
            .expect("the selected branch must be recorded as pending");
        assert_eq!(pending.fork_h, fork_h);
        clear_pending_adoption();
    }

    // ---- item 17 FORK-REORG: backfill clamp + reconciliation judge ----

    fn mk_header(prev: Hash, merkle_seed: u8, bits: u32) -> Block {
        Block {
            version: 1,
            prev_hash: prev,
            merkle_root: [merkle_seed; 32],
            time: 1_700_001_000,
            bits,
            nonce: 0,
            vtx: vec![],
            block_sig: vec![],
        }
    }

    /// (F9) the boot body span is the MEASURED shortfall, not a constant: a
    /// crash can leave up to 255 un-fsynced bodies behind tipstate.
    #[test]
    fn backfill_body_span_tracks_the_measured_store_shortfall() {
        // store in sync (shortfall 0): the configured evidence sample stands
        assert_eq!(backfill_body_span(100, Some(0), 3000), 100);
        // crash tail of 255 bodies: the span grows to cover it
        assert_eq!(backfill_body_span(100, Some(255), 3000), 255);
        // no live store / no indexed body: fall back to the configured span
        assert_eq!(backfill_body_span(100, None, 3000), 100);
        // never more bodies than the peer actually served
        assert_eq!(backfill_body_span(100, Some(255), 40), 40);
        // a shortfall smaller than the sample does not shrink the evidence
        assert_eq!(backfill_body_span(100, Some(3), 3000), 100);
    }

    /// (F9) the measured shortfall is picked CONTIGUOUSLY at the window top —
    /// the old stride stepped over exactly the bodies a crash left behind.
    #[test]
    fn backfill_pick_indices_tail_covers_the_crash_tail_contiguously() {
        let tip = 2_208_000u64;
        let start_h = tip - 3000;
        let got = 3000usize;
        let picks = backfill_pick_indices_tail(got, 255, tip, start_h, 255);
        assert_eq!(picks.len(), 255);
        // the top 255 heights are all present (contiguous), i.e. the last
        // in-window index is the newest block the store is missing
        for n in 0..255usize {
            assert!(
                picks.contains(&(got - 1 - n)),
                "tail index {} missing from the picks",
                got - 1 - n
            );
        }
        assert!(picks.windows(2).all(|w| w[0] < w[1]), "picks must be sorted");
        // a shortfall larger than the budget cannot over-request
        let capped = backfill_pick_indices_tail(got, 10, tip, start_h, 400);
        assert_eq!(capped.len(), 10);
        assert!(capped.iter().all(|i| *i < got));
        // degenerate inputs stay empty
        assert!(backfill_pick_indices_tail(0, 10, tip, start_h, 5).is_empty());
        assert!(backfill_pick_indices_tail(got, 0, tip, start_h, 5).is_empty());
    }

    #[test]
    fn backfill_pick_indices_clamp_to_the_local_window_tip() {
        // peer 100 blocks ahead: the served range (3000 + 100 headers) used
        // to be picked stride-wise across its FULL length, landing picks
        // above the local tip → "backfill block outside window" → exit(4)
        // crash-loop on every boot while a peer led
        let tip = 2_208_000u64;
        let start_h = tip - 3000;
        let picks = backfill_pick_indices(3100, 100, tip, start_h);
        assert!(!picks.is_empty());
        assert!(picks.len() < 100, "the tail above the tip must be dropped");
        for i in &picks {
            assert!(
                start_h + 1 + *i as u64 <= tip,
                "pick {} lands above the local window tip",
                i
            );
        }
        // in-window requests are unchanged
        assert_eq!(backfill_pick_indices(100, 10, tip, tip - 100).len(), 10);
        // degenerate inputs
        assert!(backfill_pick_indices(0, 100, tip, 0).is_empty());
        assert!(backfill_pick_indices(100, 0, tip, 0).is_empty());
    }

    // ---- 2026-11-13 boot-body-stall: the body phase must never exit(4) ----

    #[test]
    fn backfill_body_stall_zero_bodies_returns_ok_zero_never_a_fatal_err() {
        let _live_store_serial = lock_live_store_tests();
        // the LIVE 2026-11-13 17:20Z shape: headers validated, then the peer
        // goes silent — the body phase must return Ok(0) at the deadline
        // (the caller WARN+skips), never the old fatal
        // "backfill: no blocks validated" that exit(4)-crash-looped boots
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let addr = listener.local_addr().unwrap();
        let holder = std::thread::spawn(move || {
            // accept and HOLD the socket open, serve NOTHING
            let (_s, _) = listener.accept().unwrap();
            std::thread::sleep(std::time::Duration::from_secs(3));
        });
        let mut sess = Session::connect(&format!("127.0.0.1:{}", addr.port())).unwrap();
        let stg = synthetic_chain(100, 105);
        let rpc = Rpc::new("127.0.0.1", 1, "", "");
        let mut stats = Stats::default();
        let picks: Vec<(Hash, u64)> = (0..3u8)
            .map(|i| {
                let mut h = [0x22u8; 32];
                h[0] = i;
                (h, 103 + i as u64)
            })
            .collect();
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(1);
        let no_headers: Vec<Block> = Vec::new();
        let validated = backfill_fetch_bodies(
            &mut sess, &stg, &rpc, &mut stats, &no_headers, picks, deadline,
        )
        .expect("a body-phase stall must be Ok, never a fatal Err");
        holder.join().unwrap();
        assert_eq!(validated, 0, "nothing was served, so nothing validated");
    }

    #[test]
    fn backfill_body_peer_death_after_headers_returns_ok_never_a_fatal_err() {
        let _live_store_serial = lock_live_store_tests();
        // the server dies right after accept (Pi's "send block: Broken pipe"
        // shape seen from the other side): the pump layer errors — the OLD
        // code propagated that to finish(EXIT_PROTOCOL)
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let addr = listener.local_addr().unwrap();
        let holder = std::thread::spawn(move || {
            let (s, _) = listener.accept().unwrap();
            drop(s); // die immediately
        });
        let mut sess = Session::connect(&format!("127.0.0.1:{}", addr.port())).unwrap();
        let stg = synthetic_chain(100, 105);
        let rpc = Rpc::new("127.0.0.1", 1, "", "");
        let mut stats = Stats::default();
        let picks: Vec<(Hash, u64)> = (0..3u8)
            .map(|i| {
                let mut h = [0x23u8; 32];
                h[0] = i;
                (h, 103 + i as u64)
            })
            .collect();
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(2);
        let no_headers: Vec<Block> = Vec::new();
        let validated = backfill_fetch_bodies(
            &mut sess, &stg, &rpc, &mut stats, &no_headers, picks, deadline,
        )
        .expect("a dead peer must be Ok(validated-so-far), never a fatal Err");
        holder.join().unwrap();
        assert_eq!(validated, 0);
    }

    #[test]
    fn backfill_body_garbage_block_payload_skips_the_phase_never_a_fatal_err() {
        let _live_store_serial = lock_live_store_tests();
        // a wire-valid "block" frame whose payload is garbage: the OLD code
        // propagated the parse error to finish(EXIT_PROTOCOL) — every boot
        // against such a peer would crash-loop. Now: WARN + skip the phase.
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let addr = listener.local_addr().unwrap();
        let holder = std::thread::spawn(move || {
            let (mut s, _) = listener.accept().unwrap();
            let frame = tri7_core::p2p::encode_message("block", b"not-a-block-at-all")
                .expect("encode ok");
            use std::io::Write as _;
            let _ = s.write_all(&frame);
            std::thread::sleep(std::time::Duration::from_millis(1500));
        });
        let mut sess = Session::connect(&format!("127.0.0.1:{}", addr.port())).unwrap();
        let stg = synthetic_chain(100, 105);
        let rpc = Rpc::new("127.0.0.1", 1, "", "");
        let mut stats = Stats::default();
        let picks: Vec<(Hash, u64)> = (0..3u8)
            .map(|i| {
                let mut h = [0x24u8; 32];
                h[0] = i;
                (h, 103 + i as u64)
            })
            .collect();
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(1);
        let no_headers: Vec<Block> = Vec::new();
        let validated = backfill_fetch_bodies(
            &mut sess, &stg, &rpc, &mut stats, &no_headers, picks, deadline,
        )
        .expect("a garbage served body must be Ok(validated-so-far), never a fatal Err");
        holder.join().unwrap();
        assert_eq!(validated, 0);
        assert!(
            stats.blocks_received >= 1,
            "the garbage block frame must have been received and counted"
        );
    }

    // ---- 2026-11-25 boot-link-failure (item 50): a served body that does
    // not validate against OUR chain is the peer's branch view, never a
    // local chain problem — the body phase must skip, never exit(4) ----

    /// A one-shot TCP "peer" that serves exactly one wire-valid `block`
    /// message and then holds the socket open.
    fn one_block_peer(block: &Block) -> (Session, std::thread::JoinHandle<()>) {
        let payload = block.serialize();
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let addr = listener.local_addr().unwrap();
        let holder = std::thread::spawn(move || {
            let (mut s, _) = listener.accept().unwrap();
            let frame = tri7_core::p2p::encode_message("block", &payload).expect("encode ok");
            use std::io::Write as _;
            let _ = s.write_all(&frame);
            std::thread::sleep(std::time::Duration::from_millis(1500));
        });
        let sess = Session::connect(&format!("127.0.0.1:{}", addr.port())).unwrap();
        (sess, holder)
    }

    #[test]
    fn backfill_body_link_failure_skips_the_phase_never_a_fatal_err() {
        let _live_store_serial = lock_live_store_tests();
        // the LIVE 2026-11-25 shapes (DNS3 13:30:17Z h2219547, 13:54:31Z
        // h2219559): the first-connected peer was on the losing side of a
        // near-tied fork, so the served body carried the LOSING predecessor
        // — the OLD code let that Err reach finish(EXIT_PROTOCOL): exit 4,
        // systemd restart, the SAME peer, the same exit: a crash loop that
        // only ends when the peer reorgs. Now: WARN + skip the phase.
        let stg = synthetic_chain(100, 105);
        let loser_parent = [0x77u8; 32]; // the peer's own h104 on its branch
        let served = bin_block(loser_parent, 0x31);
        let (mut sess, holder) = one_block_peer(&served);
        let rpc = Rpc::new("127.0.0.1", 1, "", "");
        let mut stats = Stats::default();
        let picks = vec![(served.hash(), 105)];
        let no_headers: Vec<Block> = Vec::new();
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(2);
        let validated = backfill_fetch_bodies(
            &mut sess, &stg, &rpc, &mut stats, &no_headers, picks, deadline,
        )
        .expect("a served body off our chain must be Ok(validated-so-far), never a fatal Err");
        holder.join().unwrap();
        assert_eq!(validated, 0, "the non-linking body must not be counted");
        assert_eq!(stats.blocks_received, 1);
        assert_eq!(
            stats.blocks_backfill_refused, 1,
            "the refusal must be counted for the SUMMARY"
        );
    }

