    #[test]
    fn reservebalance_verb_set_contract() {
        // the reservebalance verb's write path (GUI-POLISH 2026-11-09):
        // global applied live + conf line persisted + the byte-exact v5
        // init error on any un-parseable amount. (This test binary has no
        // other stake-global users, so the process-global set here is safe.)
        let dir = crate::testsupport::test_dir("tri7-reserve-verb-test");
        let conf = dir.join("triangles.conf");
        std::fs::write(&conf, "stake=1\n").unwrap();
        // set: response shape + live global + persisted conf line
        let v = reservebalance_apply(&conf, "2.5").unwrap();
        assert_eq!(v["reservebalance"], "2.500000");
        assert_eq!(tri7_core::stake::reserve_balance(), 2_500_000);
        let text = std::fs::read_to_string(&conf).unwrap();
        assert!(
            text.contains("reservebalance=2.500000"),
            "conf line persisted, got: {text}"
        );
        // an existing line is REPLACED, not appended twice
        let v = reservebalance_apply(&conf, "0.000001").unwrap();
        assert_eq!(v["reservebalance"], "0.000001");
        let text = std::fs::read_to_string(&conf).unwrap();
        assert_eq!(text.lines().filter(|l| l.starts_with("reservebalance=")).count(), 1);
        // the exact v5 init.cpp:907 string (never substituted <amount>)
        assert_eq!(
            reservebalance_apply(&conf, "zz-not-money").unwrap_err(),
            (-8, "Invalid amount for -reservebalance=<amount>".to_string())
        );
        // negatives are ParseMoney rejections in v5
        assert_eq!(
            reservebalance_apply(&conf, "-1").unwrap_err().0,
            -8
        );
        // restore the pristine global for any later test
        tri7_core::stake::set_reserve_balance(0);
    }


    #[test]
    fn smsg_options_cmd_matches_legacy_shapes() {
        // default and explicit list
        assert_eq!(smsg_options_cmd(&serde_json::json!([])), Ok(SmsgOptionsCmd::List));
        assert_eq!(
            smsg_options_cmd(&serde_json::json!(["list"])),
            Ok(SmsgOptionsCmd::List)
        );
        // set carries both option + value
        assert_eq!(
            smsg_options_cmd(&serde_json::json!(["set", "newAddressRecv", "off"])),
            Ok(SmsgOptionsCmd::Set {
                optname: Some("newAddressRecv".into()),
                value: Some("off".into()),
            })
        );
        // set with the value missing is the legacy "Too few parameters." path
        assert_eq!(
            smsg_options_cmd(&serde_json::json!(["set", "newAddressRecv"])),
            Ok(SmsgOptionsCmd::Set {
                optname: Some("newAddressRecv".into()),
                value: None,
            })
        );
        // unknown mode renders the legacy result object (with its own typo)
        assert_eq!(
            smsg_options_cmd(&serde_json::json!(["bogus"])),
            Ok(SmsgOptionsCmd::UnknownMode)
        );
        // arity > 3 throws -8 (legacy runtime_error)
        assert_eq!(
            smsg_options_cmd(&serde_json::json!(["set", "a", "b", "c"])),
            Err((-8, "smsgoptions [list|set <optname> <value>]".to_string()))
        );
    }

    #[test]
    fn script_pushes_33_finds_only_exact_compressed_pubkey_pushes() {
        // 0x21 (33) + 33 bytes + 0xac (OP_CHECKSIG) — the P2PK form
        let mut p2pk = vec![0x21u8];
        p2pk.extend_from_slice(&[7u8; 33]);
        p2pk.push(0xac);
        let pushes = script_pushes_33(&p2pk);
        assert_eq!(pushes.len(), 1);
        assert_eq!(pushes[0], [7u8; 33].as_slice());
        // a 32-byte push (0x20) is NOT a pubkey push
        let mut p32 = vec![0x20u8];
        p32.extend_from_slice(&[7u8; 32]);
        assert!(script_pushes_33(&p32).is_empty());
        // a scriptSig carrying a signature push (var) then a 33-byte pubkey
        let mut sig = vec![71u8]; // 71-byte DER sig
        sig.extend_from_slice(&[0x30u8; 71]);
        sig.push(0x21);
        sig.extend_from_slice(&[9u8; 33]);
        let pushes = script_pushes_33(&sig);
        assert_eq!(pushes.len(), 1);
        assert_eq!(pushes[0], [9u8; 33].as_slice());
        // PUSHDATA1 form (0x4c 0x21) also yields the 33 bytes
        let mut pd1 = vec![0x4cu8, 0x21u8];
        pd1.extend_from_slice(&[3u8; 33]);
        assert_eq!(script_pushes_33(&pd1).len(), 1);
        // truncated pushes don't panic and don't match
        let mut trunc = vec![0x21u8];
        trunc.extend_from_slice(&[1u8; 20]);
        assert!(script_pushes_33(&trunc).is_empty());
    }

    // ---- repairwallet / resendtx (workqueue item 9 RPC-P1b) ----

    #[test]
    fn newest_replayable_tip_walks_back_only_over_missing_bodies() {
        // bodies exist 100..=200; the tip hint is 5 higher (headers-only tail)
        let present = |h: u64| (100..=200).contains(&h);
        let (tip, back) = newest_replayable_tip(&present, 100, 205);
        assert_eq!((tip, back), (200, 5));
        // everything present → no walk
        let (tip, back) = newest_replayable_tip(&|_| true, 100, 200);
        assert_eq!((tip, back), (200, 0));
        // nothing present → clamps at base, honest (every height 101..=205
        // was checked and failed, so back = hint - base)
        let (tip, back) = newest_replayable_tip(&|_| false, 100, 205);
        assert_eq!((tip, back), (100, 105));
        // the 5_000 cap: never walks below hint-5000
        let (tip, back) = newest_replayable_tip(&|_| false, 0, 10_000);
        assert_eq!((tip, back), (5_000, 5_000));
    }

    #[test]
    fn repairwallet_and_resendtx_arity_matches_legacy() {
        // legacy repairwallet throws on ANY parameter (runtime_error);
        // resendtx accepts at most one (ignored) parameter.
        assert!(repairwallet_params_ok(&serde_json::json!([])).is_ok());
        assert!(repairwallet_params_ok(&serde_json::Value::Null).is_ok());
        let e = repairwallet_params_ok(&serde_json::json!(["extra"])).unwrap_err();
        assert_eq!(e.0, -8);
        assert!(resendtx_params_ok(&serde_json::json!([])).is_ok());
        assert!(resendtx_params_ok(&serde_json::json!(["ignored-account"])).is_ok());
        let e = resendtx_params_ok(&serde_json::json!(["a", "b"])).unwrap_err();
        assert_eq!(e.0, -8);
    }

    // LiveOut ownership marker for the diff tests: production passes
    // WalletLive::owns (a script/key check); the diff itself only consumes
    // the predicate, so the tests mark ownership via a dedicated field.
    fn live_out(value: i64, ours: bool) -> LiveOut {
        LiveOut {
            height: 500,
            block_time: 1_700_000_000,
            tx_time: 1_700_000_000,
            tx_offset: if ours { 9_000 } else { 1 },
            value,
            script: vec![0x51],
            created_epoch: 1_700_000_000,
            coinstake: false,
            coinbase: false,
        }
    }

    #[test]
    fn repair_diff_counts_only_wallet_owned_mismatches() {
        let mut old = HashMap::new();
        let mut fresh = HashMap::new();
        // h1: ours in both → no mismatch
        let h1: Hash = [1u8; 32];
        old.insert((h1, 0), live_out(1_000, true));
        fresh.insert((h1, 0), live_out(1_000, true));
        // h2: ours in the VIEW ONLY → phantom (chain spent it)
        let h2: Hash = [2u8; 32];
        old.insert((h2, 1), live_out(2_000, true));
        // h3: ours in the REPLAY ONLY → lost (view had dropped it)
        let h3: Hash = [3u8; 32];
        fresh.insert((h3, 0), live_out(3_000, true));
        // h4/h5: NOT ours, missing on either side → must be ignored
        let h4: Hash = [4u8; 32];
        old.insert((h4, 0), live_out(4_000, false));
        let h5: Hash = [5u8; 32];
        fresh.insert((h5, 0), live_out(5_000, false));
        let owns = |o: &LiveOut| o.tx_offset == 9_000;
        let d = repair_diff(&old, &fresh, &owns);
        assert_eq!(d.count(), 2);
        assert_eq!(d.phantom, vec![((h2, 1), 2_000)]);
        assert_eq!(d.lost, vec![((h3, 0), 3_000)]);
        assert_eq!(d.amount(), 5_000);
        // identical maps → wallet check passed shape
        let d0 = repair_diff(&old, &old, &owns);
        assert_eq!(d0.count(), 0);
        assert_eq!(d0.amount(), 0);
    }

    // ---- item 27 §16-RACED-MINT-AUTOHEAL ----

    /// A real block store h0..=h4 whose h2 body pays `pubkey` the honest
    /// coin (block.time = the synthetic chain's entry time at h2), so a
    /// WalletLive::seed replay over it reproduces that coin with exact
    /// chain-slot facts — the autoheal rebuild fixture. Filler blocks carry
    /// only an empty coinbase (value 0 + empty script → never enters a live
    /// map), so the replay holds exactly ONE owned coin.
    #[test]
    fn seed_tail_by_index_crosses_the_archive_coverage_hole() {
        // (fused30) THE regression test for the GUI zero-balance freeze:
        // phase 2 of the wallet seed walks [from..=tip] through the store
        // index and must cross a coverage hole (heights with no body) onto
        // the kernel window's own chain and apply its coins. The hole is
        // COUNTED (first/last skip, tier-1.5 gap gate) — never fatal — and
        // a body that neither chains onto the anchor nor follows a gap is
        // a stale index row: counted, never applied.
        let (secret, pubkey) = tri7_core::spend::synthetic_key("seed-tail-gap");
        let _ = secret;
        let pubkey = pubkey.to_vec();
        let script = tri7_core::spend::script_pubkey_p2pk(&pubkey).unwrap();
        let coin = 7 * tri7_core::consensus::COIN;
        let mk = |h: u64, prev: Hash, pay: bool| -> Block {
            let mut b = Block {
                version: 2,
                prev_hash: prev,
                merkle_root: [0u8; 32],
                time: 1_700_000_000u32 + (h * 600) as u32,
                bits: 0x2000_ffff,
                nonce: 7,
                vtx: vec![tri7_core::legacy::Tx {
                    version: 1,
                    time: 0,
                    vin: vec![tri7_core::legacy::Vin {
                        prev_hash: [0u8; 32],
                        prev_n: u32::MAX,
                        script_sig: vec![0x02],
                        sequence: u32::MAX,
                    }],
                    vout: vec![tri7_core::legacy::Vout {
                        value: if pay { coin } else { 0 },
                        script_pubkey: if pay { script.clone() } else { vec![] },
                    }],
                    locktime: 0,
                }],
                block_sig: vec![],
            };
            b.merkle_root = b.merkle_root();
            b
        };
        // the chain h0..=h10 exists; phase 1 delivered h0..=h4 (anchor
        // hashes[4]); h5..=h7 are the hole; h8..=h10 are the kernel
        // window's own chain (h8 chains onto the hole's h7, NOT onto h4);
        // h9 pays the wallet.
        let mut chain: Vec<Block> = Vec::new();
        let mut hashes: Vec<Hash> = Vec::new();
        let mut prev = [0u8; 32];
        for h in 0..=10u64 {
            let b = mk(h, prev, h == 9);
            prev = b.hash();
            hashes.push(b.hash());
            chain.push(b);
        }
        let lookup = |h: u64| -> Option<(Block, Hash)> {
            match h {
                8..=10 => Some((chain[h as usize].clone(), hashes[h as usize])),
                _ => None, // 5..=7: the coverage hole
            }
        };
        let mut wl = wallet_live_with(&[pubkey.clone()], vec![]);
        let mut skipped = 0usize;
        let mut first_skip: Option<u64> = None;
        let mut last_skip = 0u64;
        WalletLive::seed_tail_by_index(
            &mut wl,
            &lookup,
            5,
            10,
            Some(hashes[4]),
            &mut skipped,
            &mut first_skip,
            &mut last_skip,
        );
        assert_eq!(
            first_skip, Some(5),
            "the hole's lowest height is the first skip"
        );
        assert_eq!(last_skip, 7);
        assert_eq!(skipped, 3);
        let ours: i64 = wl
            .live
            .values()
            .filter(|o| wl.owns(o))
            .map(|o| o.value)
            .sum();
        assert_eq!(ours, coin, "the window's h9 coin applied across the hole");

        // A stale/raced index row above the window: it does NOT chain onto
        // hashes[10] and follows no gap — counted as a skip, its coin NEVER
        // applied.
        let stale = mk(11, [0x0Bu8; 32], true); // prev != hashes[10]
        let stale_hash = stale.hash();
        let lookup2 = |h: u64| -> Option<(Block, Hash)> {
            if h == 11 {
                Some((stale.clone(), stale_hash))
            } else {
                lookup(h)
            }
        };
        let mut wl2 = wallet_live_with(&[pubkey], vec![]);
        let mut skipped2 = 0usize;
        let mut first_skip2: Option<u64> = None;
        let mut last_skip2 = 0u64;
        WalletLive::seed_tail_by_index(
            &mut wl2,
            &lookup2,
            5,
            11,
            Some(hashes[4]),
            &mut skipped2,
            &mut first_skip2,
            &mut last_skip2,
        );
        assert_eq!(first_skip2, Some(5));
        assert_eq!(last_skip2, 11, "the stale row itself is the last skip");
        assert_eq!(skipped2, 4);
        let ours2: i64 = wl2
            .live
            .values()
            .filter(|o| wl2.owns(o))
            .map(|o| o.value)
            .sum();
        assert_eq!(ours2, coin, "the stale row's coin was not applied");
    }

    /// (item 44 deploy r2, 2026-11-24) THE regression test for the DNS2
    /// staking stall: phase 1's file-order walk threaded the fork's LOSER
    /// (first-writer-wins; the loser is a dead side branch, so
    /// step_past_stale found no successor and the walk ended Eof with
    /// the LOSER as the phase-2 anchor). Pre-item-44 the tail above the
    /// fork was a coverage HOLE in the index: None lookups set ran_gap
    /// and the first body after the gap re-anchored the view — staking
    /// worked. The item-44 index is COMPLETE and canonical: lookup never
    /// returns None, ran_gap never fires, and every canonical body above
    /// the fork failed the chains test against the loser anchor — the
    /// whole tail was counted as "stale rows", the wallet live view lost
    /// every post-fork output, and the sole heavy staker had zero
    /// stakable candidates (the live chain stalled at h2219000, zero
    /// mints for 50+ minutes). Phase 2 must re-anchor onto the index's
    /// own linkage: when a body that follows no gap does not chain onto
    /// the file-order anchor but its prev IS the index's body at h-1,
    /// the anchor is the stale artifact — apply the body and follow the
    /// index chain from there.
    #[test]
    fn seed_tail_by_index_reanchors_past_a_file_order_fork_anchor() {
        let (secret, pubkey) = tri7_core::spend::synthetic_key("seed-tail-fork");
        let _ = secret;
        let pubkey = pubkey.to_vec();
        let script = tri7_core::spend::script_pubkey_p2pk(&pubkey).unwrap();
        let coin = 9 * tri7_core::consensus::COIN;
        let mk = |h: u64, prev: Hash, pay: bool| -> Block {
            let mut b = Block {
                version: 2,
                prev_hash: prev,
                merkle_root: [0u8; 32],
                time: 1_700_000_000u32 + (h * 600) as u32,
                bits: 0x2000_ffff,
                nonce: 7,
                vtx: vec![tri7_core::legacy::Tx {
                    version: 1,
                    time: 0,
                    vin: vec![tri7_core::legacy::Vin {
                        prev_hash: [0u8; 32],
                        prev_n: u32::MAX,
                        script_sig: vec![0x03],
                        sequence: u32::MAX,
                    }],
                    vout: vec![tri7_core::legacy::Vout {
                        value: if pay { coin } else { 0 },
                        script_pubkey: if pay { script.clone() } else { vec![] },
                    }],
                    locktime: 0,
                }],
                block_sig: vec![],
            };
            b.merkle_root = b.merkle_root();
            b
        };
        // canonical chain h0..=h10; the wallet's coin at h9 (post-fork).
        let mut chain: Vec<Block> = Vec::new();
        let mut hashes: Vec<Hash> = Vec::new();
        let mut prev = [0u8; 32];
        for h in 0..=10u64 {
            let b = mk(h, prev, h == 9);
            prev = b.hash();
            hashes.push(b.hash());
            chain.push(b);
        }
        // the fork's LOSER at h5: same prev as the canonical h5, a
        // different merkle (its own coinstake reward — pay=true makes
        // the bytes diverge), and it pays the wallet so an accidental
        // application would double the view.
        let loser = mk(5, hashes[4], true);
        assert_ne!(loser.hash(), hashes[5], "the loser is a real fork frame");
        // the COMPLETE canonical index (item 44's shape): every height
        // from 0..=10 has its body — lookup never returns None above
        // the fork, so ran_gap can never fire.
        let lookup = |h: u64| -> Option<(Block, Hash)> {
            chain
                .get(h as usize)
                .map(|b| (b.clone(), hashes[h as usize]))
        };
        // phase 1 delivered h0..=h4 then the LOSER at h5, and the walk
        // ended Eof (nothing in the file chains onto the loser). Phase 2
        // starts at h6 with the loser as the anchor.
        let mut wl = wallet_live_with(&[pubkey.clone()], vec![]);
        let mut skipped = 0usize;
        let mut first_skip: Option<u64> = None;
        let mut last_skip = 0u64;
        WalletLive::seed_tail_by_index(
            &mut wl,
            &lookup,
            6,
            10,
            Some(loser.hash()),
            &mut skipped,
            &mut first_skip,
            &mut last_skip,
        );
        assert_eq!(
            first_skip, None,
            "the complete canonical index is not a hole — nothing is skipped"
        );
        assert_eq!(last_skip, 0);
        assert_eq!(skipped, 0);
        let ours: i64 = wl
            .live
            .values()
            .filter(|o| wl.owns(o))
            .map(|o| o.value)
            .sum();
        assert_eq!(
            ours, coin,
            "the post-fork tail applied — the staker's coins are back in the view"
        );

        // The raced-row guard must still hold: an orphan row at h11
        // whose prev is NOT the index's h10 body follows no gap and
        // fails both the anchor test AND the index-linkage test —
        // counted as a skip, its coin never applied.
        let stale = mk(11, [0x0Bu8; 32], true); // prev != hashes[10]
        let stale_hash = stale.hash();
        let lookup2 = |h: u64| -> Option<(Block, Hash)> {
            if h == 11 {
                Some((stale.clone(), stale_hash))
            } else {
                lookup(h)
            }
        };
        let mut wl2 = wallet_live_with(&[pubkey], vec![]);
        let mut skipped2 = 0usize;
        let mut first_skip2: Option<u64> = None;
        let mut last_skip2 = 0u64;
        WalletLive::seed_tail_by_index(
            &mut wl2,
            &lookup2,
            6,
            11,
            Some(loser.hash()),
            &mut skipped2,
            &mut first_skip2,
            &mut last_skip2,
        );
        assert_eq!(first_skip2, Some(11), "only the orphan row is a skip");
        assert_eq!(last_skip2, 11);
        assert_eq!(skipped2, 1);
        let ours2: i64 = wl2
            .live
            .values()
            .filter(|o| wl2.owns(o))
            .map(|o| o.value)
            .sum();
        assert_eq!(
            ours2, coin,
            "the orphan's coin was not applied — index-linkage re-anchoring kept the guard"
        );
    }

    fn autoheal_store_with_honest_coin(
        dir: &std::path::Path,
        pubkey: &[u8],
        value: i64,
    ) -> std::sync::Arc<BlockStore> {
        let script = tri7_core::spend::script_pubkey_p2pk(pubkey).unwrap();
        let mut frames = Vec::new();
        let mut hashes = Vec::new();
        let mut prev = [0u8; 32];
        for h in 0..=4u64 {
            let mut b = Block {
                version: 2,
                prev_hash: prev,
                merkle_root: [0u8; 32],
                time: 1_700_000_000u32 + (h * 600) as u32,
                bits: 0x2000_ffff,
                nonce: 7,
                vtx: vec![tri7_core::legacy::Tx {
                    version: 1,
                    time: 0,
                    vin: vec![tri7_core::legacy::Vin {
                        prev_hash: [0u8; 32],
                        prev_n: u32::MAX,
                        script_sig: vec![0x01],
                        sequence: u32::MAX,
                    }],
                    vout: vec![tri7_core::legacy::Vout {
                        value: 0,
                        script_pubkey: vec![],
                    }],
                    locktime: 0,
                }],
                block_sig: vec![],
            };
            if h == 2 {
                b.vtx = vec![tri7_core::legacy::Tx {
                    version: 1,
                    time: b.time,
                    vin: vec![tri7_core::legacy::Vin {
                        prev_hash: [0u8; 32],
                        prev_n: u32::MAX,
                        script_sig: vec![0x02],
                        sequence: u32::MAX,
                    }],
                    vout: vec![tri7_core::legacy::Vout {
                        value,
                        script_pubkey: script.clone(),
                    }],
                    locktime: 0,
                }];
            }
            b.merkle_root = b.merkle_root();
            hashes.push(b.hash());
            frames.extend_from_slice(&bin_frame(&b));
            prev = b.hash();
        }
        let path = dir.join("blocks.bin");
        std::fs::write(&path, &frames).unwrap();
        let store = tri7_core::blockindex::BlockStore::new(Some(path), Some(dir.join("idx")));
        store.spawn_build(Some(tri7_core::blockindex::BuildOracle {
            base: 0,
            hashes,
            tip: 4,
        }));
        wait_store_ready(&store);
        store
    }

    /// The raced-mint episode: chain h0..=h4 whose canonical map holds the
    /// honest coin's meta plus a raced coin's meta, and a wallet live view
    /// holding both — the raced coin with the ABANDONED block's
    /// containing-block time (20s earlier, tx facts agreeing — the exact
    /// DNS3 14:21:42Z shape). Returns (stg, wl, raced_key, store).
    fn autoheal_fixture(
        tag: &str,
    ) -> (
        crate::testsupport::TestDir,
        ChainState,
        WalletLive,
        (Hash, u32),
        std::sync::Arc<BlockStore>,
    ) {
        let (secret, pubkey) = tri7_core::spend::synthetic_key(tag);
        let _ = secret;
        let pubkey = pubkey.to_vec();
        let dir = crate::testsupport::test_dir(&format!("tri7-{tag}"));
        let store = autoheal_store_with_honest_coin(
            &dir,
            &pubkey,
            50 * tri7_core::consensus::COIN,
        );
        // the honest coin as the REPLAY sees it (exact chain-slot facts)
        let wallet_keys = wallet_live_with(&[pubkey.clone()], vec![]).wallet;
        let fresh0 = WalletLive::seed(&store, wallet_keys, 0, 4).unwrap();
        let honest_key = *fresh0
            .live
            .keys()
            .find(|k| fresh0.owns(&fresh0.live[k]))
            .expect("honest coin in the replay");
        let honest = fresh0.live[&honest_key].clone();
        assert_eq!(honest.height, 2);
        let mut stg = synthetic_chain(0, 4);
        stg.utxo.map.insert(
            honest_key,
            crate::kernel::UtxoMeta {
                height: 2,
                tx_offset: honest.tx_offset,
                tx_time: honest.tx_time,
                value: honest.value,
            },
        );
        let raced_key: (Hash, u32) = ([0x5Bu8; 32], 1);
        stg.utxo.map.insert(
            raced_key,
            crate::kernel::UtxoMeta {
                height: 2,
                tx_offset: honest.tx_offset,
                tx_time: honest.tx_time, // tx facts agree…
                value: 250_592_524,
            },
        );
        let mut wl = wallet_live_with(&[pubkey], vec![(honest_key, honest.clone())]);
        wl.base = 0;
        wl.live.insert(
            raced_key,
            LiveOut {
                height: 2,
                block_time: honest.block_time - 20, // …block_time contradicts
                tx_time: honest.tx_time,
                tx_offset: honest.tx_offset,
                value: 250_592_524,
                script: honest.script.clone(),
                created_epoch: honest.block_time - 20,
                coinstake: false,
                coinbase: false,
            },
        );
        (dir, stg, wl, raced_key, store)
    }

    #[test]
    fn autoheal_due_fires_on_first_sighting_relog_cadence_and_episode_cap() {
        let mut stake_st = gate_stake_state();
        let impaired = |ticks: u64, first: &str| StaleLiveView {
            txid: "raced".into(),
            n: 1,
            wallet_height: 2,
            wallet_block_time: 1,
            chain_block_time: 2,
            wallet_tx_time: 1,
            chain_tx_time: 1,
            absent: false,
            chain_height: None,
            resolver_fault: false,
            coins: 1,
            first_utc: first.into(),
            ticks,
        };
        // first sighting fires; quiet ticks wait; the loud re-log cadence fires
        assert!(autoheal_due(&impaired(1, "e1"), &mut stake_st));
        assert!(!autoheal_due(&impaired(2, "e1"), &mut stake_st));
        assert!(!autoheal_due(&impaired(39, "e1"), &mut stake_st));
        assert!(autoheal_due(&impaired(40, "e1"), &mut stake_st));
        assert!(!autoheal_due(&impaired(41, "e1"), &mut stake_st));
        // the cap: three attempts inside one episode exhaust it…
        stake_st.autoheal_attempts = AUTOHEAL_MAX_ATTEMPTS;
        assert!(!autoheal_due(&impaired(80, "e1"), &mut stake_st));
        // …a fresh episode (the impairment fully cleared, then re-armed)
        // re-arms the budget
        assert!(autoheal_due(&impaired(1, "e2"), &mut stake_st));
        assert_eq!(stake_st.autoheal_attempts, 0, "new episode resets the budget");
    }

    #[test]
    fn autoheal_store_behind_skips_without_burning_an_attempt() {
        let mut stg = synthetic_chain(0, 4);
        stg.staking_impaired = Some(StaleLiveView {
            txid: "raced".into(),
            n: 1,
            wallet_height: 2,
            wallet_block_time: 1,
            chain_block_time: 2,
            wallet_tx_time: 1,
            chain_tx_time: 1,
            absent: false,
            chain_height: None,
            resolver_fault: false,
            coins: 1,
            first_utc: "2026-11-14T14:21:42Z".into(),
            ticks: 1,
        });
        let mut wl = wallet_live_with(&[vec![0x02u8; 33]], vec![]);
        wl.base = 0;
        // an empty store cannot serve the replay window — a TRANSIENT
        // (bodies still landing): skip, and do NOT burn the attempt budget
        let store = BlockStore::new(None, None);
        let mut stake_st = gate_stake_state();
        assert!(!autoheal_stale_live_view(
            &mut stg, &mut wl, &store, &mut stake_st, None
        ));
        assert_eq!(stake_st.autoheal_attempts, 0);
        assert_eq!(
            stake_st.autoheal_episode.as_deref(),
            Some("2026-11-14T14:21:42Z"),
            "episode recorded even on a skip"
        );
        // a later re-log tick: same shape, still no burn
        stg.staking_impaired.as_mut().unwrap().ticks = 40;
        assert!(!autoheal_stale_live_view(
            &mut stg, &mut wl, &store, &mut stake_st, None
        ));
        assert_eq!(stake_st.autoheal_attempts, 0);
    }

    // ---- item 38 WALLET-SELFSEND-UNDERHOLD ----

    /// h0..=h4 store whose h2 body carries the DNS2 2026-11-22 11:29Z
    /// self-send shape: coinbase + a coinstake-shaped tx1 + tx2 = the
    /// externally signed self-send (vin spends a wallet coin; vout0 pays the
    /// FRESH key B 100 TRI via P2PKH — the 6c3af322 → TRsxnwXe shape — and
    /// vout1 pays the FUNDED key A 15.691664 TRI change).
    fn item38_selfsend_store(
        dir: &std::path::Path,
        funded_pk: &[u8],
        fresh_pk: &[u8],
    ) -> std::sync::Arc<BlockStore> {
        let change = tri7_core::spend::script_pubkey_p2pk(funded_pk).unwrap();
        let fresh = tri7_core::spend::script_pubkey_p2pkh(fresh_pk);
        const FRESH_V: i64 = 100 * tri7_core::consensus::COIN;
        const CHANGE_V: i64 = 15_691_664; // 15.691664 TRI
        let mut frames = Vec::new();
        let mut hashes = Vec::new();
        let mut prev = [0u8; 32];
        for h in 0..=4u64 {
            let mut b = Block {
                version: 2,
                prev_hash: prev,
                merkle_root: [0u8; 32],
                time: 1_700_000_000u32 + (h * 600) as u32,
                bits: 0x2000_ffff,
                nonce: 7,
                vtx: vec![tri7_core::legacy::Tx {
                    version: 1,
                    time: 0,
                    vin: vec![tri7_core::legacy::Vin {
                        prev_hash: [0u8; 32],
                        prev_n: u32::MAX,
                        script_sig: vec![0x01],
                        sequence: u32::MAX,
                    }],
                    vout: vec![tri7_core::legacy::Vout {
                        value: 0,
                        script_pubkey: vec![],
                    }],
                    locktime: 0,
                }],
                block_sig: vec![],
            };
            if h == 2 {
                b.vtx = vec![
                    // coinbase (empty)
                    tri7_core::legacy::Tx {
                        version: 1,
                        time: b.time,
                        vin: vec![tri7_core::legacy::Vin {
                            prev_hash: [0u8; 32],
                            prev_n: u32::MAX,
                            script_sig: vec![0x02],
                            sequence: u32::MAX,
                        }],
                        vout: vec![tri7_core::legacy::Vout {
                            value: 0,
                            script_pubkey: vec![],
                        }],
                        locktime: 0,
                    },
                    // coinstake-shaped tx1: real vin, value-0 empty first vout
                    tri7_core::legacy::Tx {
                        version: 1,
                        time: b.time,
                        vin: vec![tri7_core::legacy::Vin {
                            prev_hash: [1u8; 32],
                            prev_n: 0,
                            script_sig: vec![],
                            sequence: u32::MAX,
                        }],
                        vout: vec![tri7_core::legacy::Vout {
                            value: 0,
                            script_pubkey: vec![],
                        }],
                        locktime: 0,
                    },
                    // tx2: THE SELF-SEND
                    tri7_core::legacy::Tx {
                        version: 1,
                        time: b.time,
                        vin: vec![tri7_core::legacy::Vin {
                            prev_hash: [9u8; 32],
                            prev_n: 0,
                            script_sig: vec![],
                            sequence: u32::MAX,
                        }],
                        vout: vec![
                            tri7_core::legacy::Vout {
                                value: FRESH_V,
                                script_pubkey: fresh.clone(),
                            },
                            tri7_core::legacy::Vout {
                                value: CHANGE_V,
                                script_pubkey: change.clone(),
                            },
                        ],
                        locktime: 0,
                    },
                ];
            }
            b.merkle_root = b.merkle_root();
            hashes.push(b.hash());
            frames.extend_from_slice(&bin_frame(&b));
            prev = b.hash();
        }
        let path = dir.join("blocks.bin");
        std::fs::write(&path, &frames).unwrap();
        let store = tri7_core::blockindex::BlockStore::new(Some(path), Some(dir.join("idx")));
        store.spawn_build(Some(tri7_core::blockindex::BuildOracle {
            base: 0,
            hashes,
            tip: 4,
        }));
        wait_store_ready(&store);
        store
    }

    /// The boot-time world: keys = A only, view replayed over the self-send
    /// store. The wallet FILE (path returned) holds fresh key B — the
    /// post-boot import the view never saw. (The raced-phantom trigger is
    /// added by the autoheal test itself, so the credit test's balance sees
    /// exactly the self-send's two vouts.)
    #[allow(clippy::type_complexity)]
    fn item38_fixture(
        tag: &str,
    ) -> (
        crate::testsupport::TestDir,
        ChainState,
        WalletLive,
        std::sync::Arc<BlockStore>,
        std::path::PathBuf,
        i64,
    ) {
        const CHANGE_V: i64 = 15_691_664;
        let (_sec_a, pk_a) = tri7_core::spend::synthetic_key(&format!("{tag}-funded"));
        let (sec_b, pk_b) = tri7_core::spend::synthetic_key(&format!("{tag}-fresh"));
        let pk_a = pk_a.to_vec();
        let dir = crate::testsupport::test_dir(&format!("tri7-{tag}"));
        let store = item38_selfsend_store(&dir, &pk_a, &pk_b);
        let mut wl = WalletLive::seed(
            &store,
            wallet_live_with(&[pk_a.clone()], vec![]).wallet,
            0,
            4,
        )
        .unwrap();
        wl.base = 0;
        // canonical meta for the change coin (facts straight from the replay)
        let change_k = wl
            .live
            .iter()
            .find(|(_, o)| o.value == CHANGE_V)
            .map(|(k, _)| *k)
            .expect("change coin in the replay");
        let change = wl.live[&change_k].clone();
        let mut stg = synthetic_chain(0, 4);
        stg.utxo.map.insert(
            change_k,
            crate::kernel::UtxoMeta {
                height: 2,
                tx_offset: change.tx_offset,
                tx_time: change.tx_time,
                value: change.value,
            },
        );
        // the wallet FILE gains key B (the 11:13Z import the boot missed)
        let file = dir.join("wallet-file.dat");
        bootstrap_wallet_file(&file);
        let mut wh = tri7_core::wallet::WalletHandle::open_readwrite(&file).unwrap();
        let added = wh.add_key(&sec_b, "imported").unwrap();
        wh.close();
        assert_eq!(added.pubkey, pk_b, "the file holds exactly the fresh key");
        (dir, stg, wl, store, file, CHANGE_V)
    }

    /// THE INCIDENT REGRESSION (item text bar ii): a self-send whose vout0
    /// funds a FRESH own address and vout1 the change must credit BOTH vouts
    /// once the post-boot key arrives — in the live view (in place, no
    /// rebuild) AND through the AUTOHEAL/repairwallet rebuild path.
    #[test]
    fn selfsend_credits_both_vouts_once_the_post_boot_key_arrives() {
        let (_dir, _stg, mut wl, store, file, change_v) = item38_fixture("item38-credit");
        let fresh_v = 100 * tri7_core::consensus::COIN;
        let fresh_k = wl
            .live
            .iter()
            .find(|(_, o)| o.value == fresh_v)
            .map(|(k, _)| *k)
            .expect("fresh coin in the replay");
        let change_k = wl
            .live
            .iter()
            .find(|(_, o)| o.value == change_v)
            .map(|(k, _)| *k)
            .expect("change coin in the replay");
        // THE INCIDENT: debited but never credited
        assert!(
            !wl.owns(&wl.live[&fresh_k]),
            "the boot-time keystore must not own the fresh address"
        );
        assert!(wl.owns(&wl.live[&change_k]), "change to a funded address credits");
        assert_eq!(wl.balance(), change_v, "plainbal fell by exactly the coin");
        // the refresh merges the imported key and ownership flips IN PLACE
        let fresh_file = refresh_keys_from_file(Some(&file)).expect("file readable");
        let added = merge_wallet_keys(&mut wl.wallet, fresh_file);
        assert_eq!(added.len(), 1, "exactly the imported key lands");
        assert!(wl.owns(&wl.live[&fresh_k]), "fresh own address credited");
        assert_eq!(
            wl.balance(),
            fresh_v + change_v,
            "wallet == addrindex to the coin"
        );
        // staking candidates include the fresh coin now
        let (cands, _nk, _ul, _ns) = wl.candidates();
        assert!(cands.iter().any(|c| c.txid == fresh_k.0 && c.n == fresh_k.1));
        // AND through the rebuild path: a fresh WalletLive::seed with the
        // refreshed keys credits both vouts; repair_diff sees no mismatch
        let rebuilt = WalletLive::seed(&store, wl.wallet.clone(), 0, 4).unwrap();
        assert!(rebuilt.owns(&rebuilt.live[&fresh_k]));
        assert!(rebuilt.owns(&rebuilt.live[&change_k]));
        let owns = |o: &LiveOut| wl.owns(o);
        assert_eq!(repair_diff(&wl.live, &rebuilt.live, &owns).count(), 0);
    }

    /// Merge-only discipline: existing in-memory entries (with runtime
    /// unlock state) are never touched; the same key never double-adds.
    #[test]
    fn keystore_refresh_merge_is_additive_and_idempotent() {
        let (_sa, pa) = tri7_core::spend::synthetic_key("item38-merge-a");
        let (_sb, pb) = tri7_core::spend::synthetic_key("item38-merge-b");
        let (_sc, pc) = tri7_core::spend::synthetic_key("item38-merge-c");
        let (pa, pb, pc) = (pa.to_vec(), pb.to_vec(), pc.to_vec());
        let mut wallet = wallet_live_with(&[pa.clone()], vec![]).wallet;
        wallet.keys[0].secret = [0x11; 32]; // runtime unlock state
        let mut fresh = wallet_live_with(&[pa.clone(), pb.clone()], vec![]).wallet;
        fresh.keys.iter_mut().for_each(|k| k.secret = [0x22; 32]);
        let added = merge_wallet_keys(&mut wallet, fresh);
        assert_eq!(added.len(), 1, "only the unknown pubkey lands");
        assert_eq!(added[0].pubkey, pb);
        assert_eq!(wallet.keys[0].secret, [0x11; 32], "existing key untouched");
        // a re-read carrying one more new key adds exactly that one
        let fresh2 = wallet_live_with(&[pa.clone(), pb.clone(), pc.clone()], vec![]).wallet;
        let added2 = merge_wallet_keys(&mut wallet, fresh2);
        assert_eq!(added2.len(), 1);
        assert_eq!(added2[0].pubkey, pc);
        // and a fully-known key set is a no-op
        let fresh3 = wallet_live_with(&[pa, pb, pc], vec![]).wallet;
        assert!(merge_wallet_keys(&mut wallet, fresh3).is_empty());
        assert_eq!(wallet.keys.len(), 3);
    }

    /// The full AUTOHEAL path refreshes the keystore BEFORE the replay, so
    /// the rebuilt (swapped) view owns the self-send's fresh vout too.
    #[test]
    fn autoheal_rebuild_refreshes_keys_from_the_wallet_file_first() {
        let (_dir, mut stg, mut wl, store, file, change_v) = item38_fixture("item38-autoheal");
        let fresh_v = 100 * tri7_core::consensus::COIN;
        // the raced phantom: A-owned, wallet block_time contradicts the chain
        // (the autoheal trigger class, the autoheal_fixture shape)
        let change_k = wl
            .live
            .iter()
            .find(|(_, o)| o.value == change_v)
            .map(|(k, _)| *k)
            .expect("change coin in the replay");
        let change = wl.live[&change_k].clone();
        let raced_key: (Hash, u32) = ([0x5Bu8; 32], 1);
        stg.utxo.map.insert(
            raced_key,
            crate::kernel::UtxoMeta {
                height: 2,
                tx_offset: change.tx_offset,
                tx_time: change.tx_time,
                value: 25_059_252,
            },
        );
        wl.live.insert(
            raced_key,
            LiveOut {
                height: 2,
                block_time: change.block_time - 20,
                tx_time: change.tx_time,
                tx_offset: change.tx_offset,
                value: 25_059_252,
                script: change.script.clone(),
                created_epoch: change.block_time - 20,
                coinstake: false,
                coinbase: false,
            },
        );
        // trigger: the raced phantom is the facts-mismatch class
        let (cands, _nk, _ul, _ns) = wl.candidates();
        let (_rel, stale, _unres, _) = resolve_stake_evidence(&stg, &mut DupEvidence::none(), cands);
        assert_eq!(stale.len(), 1);
        assert!(!stale[0].absent);
        note_stale_evidence(&mut stg, &stale, None);
        let mut stake_st = gate_stake_state();
        assert!(
            autoheal_stale_live_view(&mut stg, &mut wl, &store, &mut stake_st, Some(&file)),
            "the rebuild ran and swapped"
        );
        assert_eq!(stake_st.autoheal_attempts, 1);
        assert!(!wl.live.contains_key(&raced_key), "raced phantom removed");
        let fresh_k = wl
            .live
            .iter()
            .find(|(_, o)| o.value == fresh_v)
            .map(|(k, _)| *k)
            .expect("fresh coin survived the swap");
        assert!(
            wl.owns(&wl.live[&fresh_k]),
            "the rebuilt view owns the self-send's fresh vout"
        );
        assert_eq!(
            wl.balance(),
            fresh_v + change_v,
            "the swapped view serves the whole wallet"
        );
    }

    /// Unreadable wallet files (no path, missing file, ENCRYPTED container)
    /// are a silent skip — the caller stays on its current keys.
    #[test]
    fn keystore_refresh_skips_unreadable_wallet_files() {
        assert!(refresh_keys_from_file(None).is_none());
        assert!(refresh_keys_from_file(Some(std::path::Path::new(
            "/nonexistent/item38-no-such-wallet.dat"
        )))
        .is_none());
        let dir = crate::testsupport::test_dir("tri7-item38-enc");
        let file = dir.join("enc.dat");
        let conn = rusqlite::Connection::open(&file).unwrap();
        conn.execute_batch(&format!(
            "PRAGMA application_id = {}; CREATE TABLE main (key BLOB PRIMARY KEY NOT NULL, value BLOB NOT NULL);",
            tri7_core::wallet::WALLET_APP_ID
        ))
        .unwrap();
        // one mkey row is enough to mark the container encrypted
        conn.execute(
            "INSERT INTO main (key, value) VALUES (?1, ?2)",
            [vec![4u8, b'm', b'k', b'e', b'y', 0u8], vec![0u8]],
        )
        .unwrap();
        drop(conn);
        assert!(refresh_keys_from_file(Some(&file)).is_none());
    }

    #[test]
    fn autoheal_rebuild_removes_the_raced_phantom_and_keeps_the_honest_coin() {
        let (_dir, mut stg, mut wl, raced_key, store) = autoheal_fixture("autoheal-rebuild");
        // detect: the raced coin is the facts-MISMATCH class (absent:false)
        let (cands, _nk, _ul, _ns) = wl.candidates();
        assert_eq!(cands.len(), 2, "honest + raced, both candidates");
        let (_rel, stale, _unres, _) = resolve_stake_evidence(&stg, &mut DupEvidence::none(), cands);
        assert_eq!(stale.len(), 1);
        assert!(!stale[0].absent, "the raced-mint shape is a facts mismatch");
        note_stale_evidence(&mut stg, &stale, None);
        let first_utc = stg.staking_impaired.as_ref().unwrap().first_utc.clone();
        let honest_before = wl.live.values().find(|o| o.height == 2 && o.value != 250_592_524).unwrap().clone();

        // heal: one in-process pass removes the phantom, keeps the honest
        // coin with identical facts, burns exactly one attempt
        let mut stake_st = gate_stake_state();
        assert!(autoheal_stale_live_view(
            &mut stg, &mut wl, &store, &mut stake_st, None
        ));
        assert_eq!(stake_st.autoheal_attempts, 1);
        assert_eq!(stake_st.autoheal_episode.as_deref(), Some(first_utc.as_str()));
        assert!(!wl.live.contains_key(&raced_key), "raced phantom removed");
        let kept = wl
            .live
            .values()
            .find(|o| o.value != 250_592_524)
            .expect("honest coin kept");
        assert_eq!(kept.block_time, honest_before.block_time);
        assert_eq!(kept.tx_time, honest_before.tx_time);
        assert_eq!(kept.tx_offset, honest_before.tx_offset);
        assert_eq!(kept.value, honest_before.value);

        // re-resolve on the rebuilt view: evidence matches → clear
        let (c2, _nk, _ul, _ns) = wl.candidates();
        let (_rel2, stale2, _unres2, _) = resolve_stake_evidence(&stg, &mut DupEvidence::none(), c2);
        assert!(stale2.is_empty(), "rebuilt view matches the chain");
        stg.staking_impaired = None;
        assert!(stg.staking_impaired.is_none());
    }

