    /// getrawchangeaddress through NodeOps::call: a stray parameter is the
    /// help error (blocker 1 — the zero-arg discipline), no wallet is the
    /// honest error, and a fresh wallet file gets a fresh bare address per
    /// call.
    #[test]
    fn getrawchangeaddress_via_nodeops_validates_then_issues() {
        let state = rpcops_state_dir("changeaddr");
        let adapter = ops_adapter_for_tests(&state, Vec::new(), None);

        // extra parameter → help, before any wallet check
        let err = tri7_core::rpc::NodeOps::call(&adapter, "getrawchangeaddress", &serde_json::json!(["bech32"]))
            .unwrap_err();
        assert_eq!(err, (-8, GETRAWCHANGEADDRESS_HELP.to_string()));
        // no wallet loaded → the honest error
        let err = tri7_core::rpc::NodeOps::call(&adapter, "getrawchangeaddress", &serde_json::json!([]))
            .unwrap_err();
        assert_eq!(err.1, "no wallet loaded (start the node with --wallet)");

        // fresh wallet → a bare change address string, fresh per call
        let wallet = state.join("wallet.dat");
        tri7_core::wallet::create_wallet_file(&wallet).unwrap();
        let adapter = ops_adapter_for_tests(&state, Vec::new(), Some(wallet));
        let a1 = tri7_core::rpc::NodeOps::call(&adapter, "getrawchangeaddress", &serde_json::json!([]))
            .expect("issues an address");
        let a2 = tri7_core::rpc::NodeOps::call(&adapter, "getrawchangeaddress", &serde_json::json!([]))
            .expect("issues a second address");
        assert!(a1.is_string() && !a1.as_str().unwrap().is_empty());
        assert_ne!(a1, a2, "each call issues a fresh key");
        let _ = std::fs::remove_dir_all(&state);
    }

    /// Blocker-2 regression: an unpersistable store must surface as the RPC
    /// error — addnode acks only what hit the disk. Two failure shapes: the
    /// atomic rename blocked (peers.json is a directory) and the tmp
    /// sidecar write blocked (peers.json.tmp is a directory; works under a
    /// root test runner, where permission bits would not).
    #[test]
    fn addnode_save_failure_propagates_to_the_rpc_error() {
        let node = rpcops_test_node(4);
        let host = node.rsplit_once(':').unwrap().0;

        // (a) peers.json is a directory: the load reads an empty default,
        // the add mutates, the atomic rename fails — the ack must fail.
        let state = rpcops_state_dir("savefail-rename");
        std::fs::create_dir_all(state.join("peers.json")).unwrap();
        let adapter = ops_adapter_for_tests(&state, Vec::new(), None);
        let err = tri7_core::rpc::NodeOps::call(&adapter, "addnode", &serde_json::json!([node, "add"]))
            .unwrap_err();
        assert_eq!(err.0, -1);
        assert!(
            err.1.contains("peer store save failed"),
            "got {err:?}"
        );
        let _ = std::fs::remove_dir_all(&state);

        // (b) the tmp sidecar is a directory: the pre-seeded row loads fine
        // and remove mutates, but the tmp write fails — the remove must not
        // ack, and the row must still be on disk.
        let state = rpcops_state_dir("savefail-tmp");
        let mut store = tri7_core::peers::PeerStore::default();
        store.upsert(host, 24113, 1, "addnode", 1);
        store.save(&state.join("peers.json")).unwrap();
        // STATE-LOCK (F1): the tmp sidecar is pid-unique now, so block THAT
        // path — the intent (a failing tmp write must not ack) is unchanged.
        std::fs::create_dir_all(
            state.join(format!("peers.json.tmp.{}", std::process::id())),
        )
        .unwrap();
        let adapter = ops_adapter_for_tests(&state, Vec::new(), None);
        let err = tri7_core::rpc::NodeOps::call(&adapter, "addnode", &serde_json::json!([node, "remove"]))
            .unwrap_err();
        assert!(
            err.1.contains("peer store save failed"),
            "got {err:?}"
        );
        let store = tri7_core::peers::PeerStore::load(&state.join("peers.json"));
        assert!(
            store.peers().iter().any(|e| e.host == host),
            "the destructive update must not have silently persisted"
        );
        let _ = std::fs::remove_dir_all(&state);
    }

    /// A corrupt peers.json is the documented tolerant-load case: addnode
    /// recovers (empty start per PeerStore::load) and the successful save
    /// replaces the junk with a valid store containing the new row.
    #[test]
    fn corrupt_peer_store_recovers_on_the_next_addnode() {
        let state = rpcops_state_dir("corrupt");
        std::fs::write(state.join("peers.json"), "not json at all {{{{").unwrap();
        let adapter = ops_adapter_for_tests(&state, Vec::new(), None);
        let node = rpcops_test_node(5);
        tri7_core::rpc::NodeOps::call(&adapter, "addnode", &serde_json::json!([node, "add"]))
            .expect("a corrupt store recovers");
        let text = std::fs::read_to_string(state.join("peers.json")).unwrap();
        assert!(text.trim_start().starts_with('{'), "file rewritten as JSON");
        let store = tri7_core::peers::PeerStore::load(&state.join("peers.json"));
        assert_eq!(store.peers().len(), 1);
        let _ = std::fs::remove_dir_all(&state);
    }

    /// Blocker-3 regression: RPC-side addnode writes and loop-side store
    /// writes racing on one peers.json ALL survive — every one of the
    /// RPC+loop updates is present in the final file, and the total is
    /// exact. (The pre-lock load→modify→save let a later writer resurrect a
    /// stale snapshot and drop earlier updates.)
    #[test]
    fn peer_store_concurrent_writes_do_not_lose_updates() {
        const RPC_WRITERS: usize = 4;
        const LOOP_WRITERS: usize = 4;
        const WRITES_PER_WRITER: usize = 20;
        let state = std::sync::Arc::new(rpcops_state_dir("concurrent"));
        let adapter =
            std::sync::Arc::new(ops_adapter_for_tests(&state, Vec::new(), None));

        let mut handles = Vec::new();
        // RPC threads: the real addnode verb, add
        for r in 0..RPC_WRITERS {
            let adapter = std::sync::Arc::clone(&adapter);
            handles.push(std::thread::spawn(move || {
                for i in 0..WRITES_PER_WRITER {
                    let node = rpcops_test_node(((r * WRITES_PER_WRITER + i + 1) as u64));
                    tri7_core::rpc::NodeOps::call(&*adapter, "addnode", &serde_json::json!([node, "add"]))
                        .unwrap_or_else(|e| panic!("rpc addnode {node} failed: {e:?}"));
                }
            }));
        }
        // loop threads: the real loop-side helper (the addr-gossip/bookkeeping
        // path: upsert + record_ok under with_peer_store_at)
        for j in 0..LOOP_WRITERS {
            let state = std::sync::Arc::clone(&state);
            handles.push(std::thread::spawn(move || {
                for i in 0..WRITES_PER_WRITER {
                    let host = format!(
                        "loop{j:02}{i:02}aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa.onion"
                    );
                    let now = tri7_core::peers::unix_now();
                    with_peer_store_at(&*state, |store| {
                        store.upsert(&host, 24113, 1, "listen", now);
                        store.record_ok(&host, 24113, now);
                    });
                }
            }));
        }
        for h in handles {
            h.join().expect("writer thread did not panic");
        }

        let store = tri7_core::peers::PeerStore::load(&state.join("peers.json"));
        let expect_total = (RPC_WRITERS + LOOP_WRITERS) * WRITES_PER_WRITER;
        let mut missing = Vec::new();
        for r in 0..RPC_WRITERS {
            for i in 0..WRITES_PER_WRITER {
                let n = (r * WRITES_PER_WRITER + i + 1) as u64;
                let host = rpcops_test_node(n).rsplit_once(':').unwrap().0.to_string();
                if !store.contains(&host, 24113) {
                    missing.push(host);
                }
            }
        }
        for j in 0..LOOP_WRITERS {
            for i in 0..WRITES_PER_WRITER {
                let host = format!(
                    "loop{j:02}{i:02}aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa.onion"
                );
                let row = store.peers().iter().find(|e| e.host == host);
                match row {
                    Some(e) if e.ok_count > 0 => {}
                    _ => missing.push(host),
                }
            }
        }
        assert!(
            missing.is_empty(),
            "{} lost update(s) of {expect_total}: {:?}",
            missing.len(),
            &missing[..missing.len().min(5)]
        );
        assert_eq!(
            store.peers().len(),
            expect_total,
            "exactly one row per write, no resurrected duplicates"
        );
        let _ = std::fs::remove_dir_all(&*state);
    }

    // -------------------------------------------------------------------
    // i2p lane: seed floor, self-advertise, per-transport windows, demotion
    // exemption, inbound transport classification
    // -------------------------------------------------------------------

    /// (i2p-stack follow-up, judge-grade blocker class) a bare machine — no
    /// explicit peer flags, empty conf — must STILL arm the from-zero path:
    /// augment_default_seeds fills cfg.peers with the embedded seed floor,
    /// and the boot gate reads `explicit_peers || !cfg.peers.is_empty()`.
    /// The r3 tree defined + tested the seeds but this gate kept them
    /// unreachable on exactly the fresh machines they exist for: try_connect
    /// never ran, peers stayed empty, seeding died instantly.
    #[test]
    fn bare_machine_without_explicit_peers_still_arms_from_zero() {
        let _tdir = crate::testsupport::test_dir("tri7-bare-machine");
        let conf_path = _tdir.join("tri7-bare-machine-test.conf");
        std::fs::write(&conf_path, "rpcuser=t\nrpcpassword=t\n").expect("write temp conf");
        let argv: Vec<String> = vec![
            "--state-dir".to_string(),
            _tdir.join("tri7-bare-machine-state").display().to_string(),
            "--conf".to_string(),
            conf_path.to_string_lossy().to_string(),
        ];
        let cfg = parse_args(&argv);
        // the seed floor is in cfg.peers even with zero user flags
        assert!(
            cfg.peers.iter().any(|t| t.transport == Transport::I2p),
            "embedded i2p seed must be present in cfg.peers on a bare machine"
        );
        assert!(
            cfg.peers.iter().any(|t| t.transport == Transport::Tor),
            "embedded tor seed must be present in cfg.peers on a bare machine"
        );
        // the boot gate: !have_state && (explicit_peers || !peers.is_empty())
        let have_state = false;
        let from_zero = cfg.sync_from_zero
            || (!have_state && (cfg.explicit_peers || !cfg.peers.is_empty()));
        assert!(
            from_zero,
            "bare machine must arm from-zero (seeds make it self-sufficient)"
        );
    }

    /// HIGH-5: every DEFAULT_PEER_SEEDS entry parses through PeerTarget and
    /// the parsed transport matches the documented tag — the table is the
    /// boot floor, a typo here would silently strand a transport.
    #[test]
    fn default_peer_seeds_parse_with_expected_transports() {
        let socks = ("127.0.0.1".to_string(), 9050);
        let i2p = ("127.0.0.1".to_string(), 4447);
        let targets = seed_targets(&socks, &i2p);
        assert_eq!(targets.len(), DEFAULT_PEER_SEEDS.len(), "every seed parses");
        // operator policy 2026-11-13: Triangles is NEVER on public clearnet —
        // the compiled seed floor must stay overlay-only (tor onion / i2p)
        for (tag, spec) in DEFAULT_PEER_SEEDS {
            assert!(
                *tag != "clearnet" && !spec.starts_with("46.62.") && !spec.starts_with("100."),
                "seed floor went back on clearnet: {tag} {spec}"
            );
        }
        for ((tag, spec), t) in DEFAULT_PEER_SEEDS.iter().zip(&targets) {
            let want = match *tag {
                "tor" => Transport::Tor,
                "i2p" => Transport::I2p,
                _ => Transport::Clearnet,
            };
            assert_eq!(
                t.transport, want,
                "seed {spec} tagged {tag} must parse to the same transport"
            );
            assert_eq!(t.endpoint(), *spec);
        }
        // the overlay seeds dial through the RIGHT socks endpoints
        let i2p_seed = targets
            .iter()
            .find(|t| t.transport == Transport::I2p)
            .expect("an i2p seed exists");
        assert_eq!(i2p_seed.socks.as_ref().unwrap().1, 4447);
        let tor_seed = targets
            .iter()
            .find(|t| t.transport == Transport::Tor)
            .expect("a tor seed exists");
        assert_eq!(tor_seed.socks.as_ref().unwrap().1, 9050);
        // the fleet identities are the live ones
        assert!(DEFAULT_PEER_SEEDS.iter().any(|(_, s)| s
            .starts_with("ztj5lcg4tgcn7lh7wlrgvmfhf42itoetwgh42doogu7w3gdhxtbq.b32.i2p")));
        assert!(DEFAULT_PEER_SEEDS.iter().any(|(_, s)| s
            .starts_with("gxvrhv3qitnc6kobrhsrse46bmcfitnybapor3or3oczzuxn6hfzxyid.onion")));
    }

    /// HIGH-5: parse_args APPENDS the seed floor (augment, never replace)
    /// and a user target equal to a seed never duplicates.
    #[test]
    fn parse_args_appends_default_seeds_without_duplicates() {
        let state = crate::testsupport::test_dir("i2pseeds");
        // (a) a bare boot (only state dir + a missing conf): the default
        // loopback target PLUS the full seed floor
        let argv = vec![
            "--state-dir".to_string(),
            state.display().to_string(),
            "--conf".to_string(),
            state.join("empty.conf").display().to_string(),
        ];
        let cfg = parse_args(&argv);
        assert!(
            cfg.peers
                .iter()
                .any(|t| t.transport == Transport::I2p && t.host.ends_with(".b32.i2p")),
            "the i2p seed must be in the boot target list: {:?}",
            cfg.peers.iter().map(|t| t.endpoint()).collect::<Vec<_>>()
        );
        assert!(
            cfg.peers.iter().any(|t| t.transport == Transport::Tor),
            "the tor seed must be in the boot target list"
        );
        // (b) a user config that ALREADY names the i2p seed: no duplicate,
        // and the user target stays in FRONT of the appended floor
        let seed_spec = "ztj5lcg4tgcn7lh7wlrgvmfhf42itoetwgh42doogu7w3gdhxtbq.b32.i2p:24113";
        let argv2 = vec![
            "--state-dir".to_string(),
            state.display().to_string(),
            "--conf".to_string(),
            state.join("empty.conf").display().to_string(),
            "--i2p".to_string(),
            seed_spec.to_string(),
        ];
        let cfg2 = parse_args(&argv2);
        let count = cfg2
            .peers
            .iter()
            .filter(|t| t.host == "ztj5lcg4tgcn7lh7wlrgvmfhf42itoetwgh42doogu7w3gdhxtbq.b32.i2p")
            .count();
        assert_eq!(count, 1, "the user's own seed target wins, no dup");
        assert_eq!(cfg2.peers[0].endpoint(), seed_spec);
    }

    /// MED-4d: overlay_addr_me reads the supervisor-written state files and
    /// builds the wire form with the is_i2p flag; an unknown identity or a
    /// --no-listen follower yields None (call sites keep the placeholder).
    #[test]
    fn overlay_addr_me_carries_i2p_flag_and_gates_on_listen() {
        let state = crate::testsupport::test_dir("i2paddrme");
        // no identity → None
        assert!(overlay_addr_me(&state, Some(24113)).is_none());
        // listener off → None even WITH an identity (never advertise an
        // address nothing listens behind)
        std::fs::write(
            state.join("i2p_destination.txt"),
            "ztj5lcg4tgcn7lh7wlrgvmfhf42itoetwgh42doogu7w3gdhxtbq.b32.i2p:24113\n",
        )
        .unwrap();
        assert!(
            overlay_addr_me(&state, None).is_none(),
            "--no-listen must not advertise"
        );
        // identity + listener → the i2p wire form with the flag
        let addr = overlay_addr_me(&state, Some(24113)).expect("the destination parses");
        assert!(addr.is_i2p);
        assert!(!addr.is_tor_v3);
        assert_eq!(addr.port, 24113);
        assert_eq!(
            addr.i2p_hostname().unwrap(),
            "ztj5lcg4tgcn7lh7wlrgvmfhf42itoetwgh42doogu7w3gdhxtbq.b32.i2p"
        );
        // garbage in the file is skipped (logged), falls through to None
        std::fs::write(state.join("i2p_destination.txt"), "not-a-destination\n").unwrap();
        assert!(overlay_addr_me(&state, Some(24113)).is_none());
        // tor fallback: a hostname file yields the onion wire form
        std::fs::remove_file(state.join("i2p_destination.txt")).unwrap();
        std::fs::write(
            state.join("onion_address.txt"),
            "gxvrhv3qitnc6kobrhsrse46bmcfitnybapor3or3oczzuxn6hfzxyid.onion\n",
        )
        .unwrap();
        let onion = overlay_addr_me(&state, Some(24113)).expect("onion identity parses");
        assert!(onion.is_tor_v3);
        assert!(!onion.is_i2p);
        assert_eq!(onion.port, 24113);
    }

    /// MED-3a: the i2p dial windows are wider than clearnet/tor (tunnel
